Amount calcAmount(WMSOrderTrans _wMSOrderTrans)
{
    //todo: check what is the amoutn if partially picked
    return this.getInvoiceAmount(_wMSOrderTrans);
}

private Amount getInvoiceAmount(WMSOrderTrans _wMSOrderTrans)
{
    SalesLine salesLine;
    Amount ret;

    while select firstonly salesLine
        where salesLine.inventTransId == _wMSOrderTrans.inventTransId
    {
        if(customerMDFSetupTable.IncludeTaxesInThreshold)
        {
            ret = ret + salesLine.LineAmount;
        }
        else
        {
            ret = ret + salesLine.lineAmountExclTax();
        }
    }

    return ret;
}
